package com.wiseway.service;
import com.wiseway.api.ApiDtos.*; import com.wiseway.domain.*; import java.math.BigDecimal; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Autowired;
@Service public class RecommendationService {
 private final LocationService catalog; private final RoutingProvider routing; private final FareCalculationService fares; private final TransitRoutingProvider transit;
 @Autowired public RecommendationService(LocationService c,RoutingProvider r,FareCalculationService f,TransitRoutingProvider t){catalog=c;routing=r;fares=f;transit=t;}
 public RecommendationService(LocationService c,RoutingProvider r,FareCalculationService f){this(c,r,f,(a,b,m)->Optional.empty());}
 public CompareResponse compare(CompareRequest r,Set<String> excluded){
  var from=location(r.origin(),r.originLatitude(),r.originLongitude()); var to=location(r.destination(),r.destinationLatitude(),r.destinationLongitude());
  if(from.isEmpty()||to.isEmpty()) return empty("UNKNOWN_LOCATION","Select a valid location suggestion before comparing.");
  var route=routing.route(from.get(),to.get());
  var mapped=transit(from.get(),to.get());
  if(route.isEmpty()) {
   var walking=walkingOption(from.get(),to.get());
   return new CompareResponse(mapped.isEmpty()?"WALKING_FALLBACK":"TRANSIT_AND_WALKING_FALLBACK",
     "OSRM road geometry was unavailable. Walking is an approximate straight-line connection; mapped transit remains schedule-unknown.",
     List.of(optionResponse(walking,"APPROXIMATE")),List.of(),false,
     mapped.isEmpty()?"Approximate walking connection available; no mapped transit coverage was found.":"Walking fallback plus mapped transit journeys are available.",
     null,null,null,null,mapped);
  }
  var verified=Set.<String>of(); var options=new ArrayList<TransportOption>();
  // OSRM constructs a road journey only. Never relabel that geometry as metro, bus, or train.
  for(var mode:List.of(TransportMode.AUTO,TransportMode.CAB)){var fare=fares.calculate(mode,(int)Math.round(route.get().distanceMetres())); if(fare.amount()!=null) options.add(new TransportOption(mode.name().toLowerCase()+"-route",mode,Math.max(1,(int)Math.round(route.get().durationSeconds()/60)),fare.amount(),"INR",0,mode==TransportMode.CAB?1:2,"Direct "+mode.name().toLowerCase()+" using the OSRM road route."));}
  options.add(walkingOption(from.get(),to.get(),route.get().distanceMetres()));
  var c=r.constraints(); var result=RecommendationEngine.recommend(options,r.preference()==null?PreferenceProfile.BALANCED:r.preference(),new RecommendationEngine.Constraints(c==null?null:c.maxFare(),r.departureAt(),c==null?null:c.arriveBy()),excluded);
  return new CompareResponse("ROUTE_"+route.get().source(),"Distance and duration from "+route.get().source()+". Transit data is mapped OSM data; schedules, fares and live service are unknown.",result.feasible().stream().map(x->option(x,route.get(),verified)).toList(),result.infeasible().stream().map(x->new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),null,List.of(),x.reasons(),verified.contains(x.option().mode().name())?"AVAILABLE":(x.option().mode()==TransportMode.AUTO||x.option().mode()==TransportMode.CAB?"ESTIMATED_ONLY":"UNKNOWN"),fareType(x.option().mode()),route.get().source())).toList(),result.noFit(),result.message(),route.get().distanceMetres(),route.get().durationSeconds(),route.get().geometry(),route.get().source(),mapped);
 }
 private TransportOption walkingOption(LocationService.Location from,LocationService.Location to){return walkingOption(from,to,haversine(from.latitude(),from.longitude(),to.latitude(),to.longitude()));}
 private TransportOption walkingOption(LocationService.Location from,LocationService.Location to,double metres){int minutes=Math.max(1,(int)Math.ceil(metres/1.25/60));return new TransportOption("walking-route",TransportMode.WALK,minutes,BigDecimal.ZERO,"INR",0,minutes,"Approximate walking connection from "+from.name()+" to "+to.name()+"; straight-line estimate, not a mapped footpath.");}
 private OptionResponse optionResponse(TransportOption o,String source){return new OptionResponse(o.id(),o.mode(),o.durationMinutes(),o.estimatedFare(),o.currency(),o.transfers(),o.walkingMinutes(),o.description(),null,List.of("Only a straight-line walking fallback was available."),List.of(),"ESTIMATED_ONLY","APPROXIMATE_ESTIMATE",source);}
 private double haversine(double aLat,double aLon,double bLat,double bLon){var p=Math.PI/180;var x=.5-Math.cos((bLat-aLat)*p)/2+Math.cos(aLat*p)*Math.cos(bLat*p)*(1-Math.cos((bLon-aLon)*p))/2;return 12742000*Math.asin(Math.sqrt(x));}
 private Optional<LocationService.Location> location(String name,Double lat,Double lon){return catalog.resolve(name).or(()->lat!=null&&lon!=null?Optional.of(new LocationService.Location("resolved",name,"Selected location",lat,lon)):Optional.empty());}
 public PlanBResponse planB(PlanBRequest r){var excluded=new HashSet<>(Optional.ofNullable(r.excludeOptionIds()).orElse(List.of()));var profile=switch(r.scenario()){case RUNNING_LATE,MISSED_SERVICE,ROUTE_DISRUPTED->PreferenceProfile.TIME_SAVER;case SAVE_MONEY,EXTRA_TIME->PreferenceProfile.BUDGET_SAVER;};var c=compare(new CompareRequest(r.origin(),r.destination(),r.originLatitude(),r.originLongitude(),r.destinationLatitude(),r.destinationLongitude(),r.departureAt(),profile,r.constraints()),excluded);var explanation=scenarioExplanation(r.scenario());return new PlanBResponse(r.scenario(),c.dataQuality(),"Simulated Plan B: "+explanation+" Not a live disruption alert.",c.feasibleOptions().isEmpty()?null:c.feasibleOptions().get(0),c.feasibleOptions().size()>1?c.feasibleOptions().subList(1,c.feasibleOptions().size()):List.of(),c.noFeasibleOption(),c.message()==null?explanation:c.message()+" "+explanation,c.routeDistanceMetres(),c.routeDurationSeconds(),c.routeGeometry(),c.routeSource(),c.transitJourneys());}
 private String scenarioExplanation(PlanBScenario s){return switch(s){case RUNNING_LATE->"Prioritized shorter estimated duration.";case MISSED_SERVICE->"Excluded the simulated missed bus service and prioritized time.";case ROUTE_DISRUPTED->"Applied the simulated disruption exclusion and prioritized time.";case SAVE_MONEY->"Prioritized the lowest estimated fare.";case EXTRA_TIME->"Prioritized cheaper options because extra time is available.";};}
 private OptionResponse option(RecommendationEngine.RankedOption x,RoutingProvider.Route r,Set<String> v){return new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),x.score(),x.reasons(),List.of(),v.contains(x.option().mode().name())?"AVAILABLE":(x.option().mode()==TransportMode.AUTO||x.option().mode()==TransportMode.CAB?"ESTIMATED_ONLY":"UNKNOWN"),fareType(x.option().mode()),r.source()+" · "+Math.round(r.distanceMetres())+"m road route");}
 private String fareType(TransportMode m){return m==TransportMode.AUTO||m==TransportMode.CAB?"CALCULATED_ESTIMATE":"ILLUSTRATIVE_ESTIMATE";}
 private List<TransitJourneyResponse> transit(LocationService.Location a,LocationService.Location b){try{return transit.journeys(a,b,Set.of(TransportMode.BUS,TransportMode.METRO,TransportMode.TRAIN)).stream().map(this::journey).toList();}catch(RuntimeException e){return List.of();}}
 private TransitJourneyResponse journey(TransitRoutingProvider.Itinerary i){var stable=String.valueOf(Objects.hash(i.source(),i.legs().stream().map(x->x.mode()+"|"+x.routeName()+"|"+x.fromStop()+"|"+x.toStop()).toList()));return new TransitJourneyResponse("transit-"+stable,i.legs().get(0).mode(),i.legs().size()==1?"DIRECT":"MULTIMODAL",i.legs().stream().map(TransitRoutingProvider.Leg::routeName).toList(),i.legs().stream().flatMap(x->java.util.stream.Stream.of(x.fromStop(),x.toStop())).toList(),i.legs().size()>1?i.legs().get(0).toStop():null,i.legs().stream().map(TransitRoutingProvider.Leg::geometryGeoJson).toList(),i.legs().stream().map(x->x.mode().name()).toList(),i.source(),"MAPPED_OSM_NO_SCHEDULE");}
 private CompareResponse empty(String q,String m){return new CompareResponse(q,m,List.of(),List.of(),true,m,null,null,null,null,List.of());}
}
